service.method:

SELECT
	  APP_LINE_CODE
	, APP_LINE_NAME
FROM SGWMG
WHERE	HOUSE_CODE			= ${session.HOUSE_CODE}
	AND COMPANY_CODE		= ${session.COMPANY_CODE}
	AND USER_ID				= ${session.ID}
	AND #DB_OWNER#NVL(DEL_FLAG, 'N')	= 'N'


INSERT INTO SGWMG
 ( 
     HOUSE_CODE
   , COMPANY_CODE
   , USER_ID
   , APP_LINE_CODE
   , APP_LINE_NAME
   , ADD_DATE
   , ADD_TIME
   , ADD_USER_ID
   , DEL_FLAG
 ) 
 VALUES
 ( 
     ${session.HOUSE_CODE}
   , ${session.COMPANY_CODE}
   , ${session.ID}
   , ${APP_LINE_CODE}
   , ${APP_LINE_NAME}
   , ${current.DATE}
   , ${current.TIME}
   , ${session.ID}
   , 'N'
 )


UPDATE SGWMG SET
	  APP_LINE_NAME		= ${APP_LINE_NAME}
	, CHANGE_DATE		= ${current.DATE}
	, CHANGE_TIME		= ${current.TIME}
	, CHANGE_USER_ID	= ${session.ID}
WHERE	HOUSE_CODE		= ${session.HOUSE_CODE}
	AND COMPANY_CODE	= ${session.COMPANY_CODE}
	AND USER_ID			= ${session.ID}
	AND APP_LINE_CODE	= ${APP_LINE_CODE}


DELETE FROM SGWML
WHERE	HOUSE_CODE    = ${session.HOUSE_CODE}
	AND COMPANY_CODE  = ${session.COMPANY_CODE}
	AND APP_LINE_CODE = ${APP_LINE_CODE}


UPDATE SGWMG SET
	DEL_FLAG = 'Y'
WHERE	HOUSE_CODE		= ${session.HOUSE_CODE}
	AND COMPANY_CODE	= ${session.COMPANY_CODE}
	AND USER_ID			= ${session.ID}
	AND APP_LINE_CODE	= ${APP_LINE_CODE}
